   'audio_picture', null::jsonb),
  ('dbc84e97-477f-5f2a-883a-608cb9e32a38', (select id from public.skills where slug = 'read-gk-vocabulary'), 'hard',
   $q$Big, huge, gigantic. Gigantic means even bigger than huge. Which one is gigantic, big enough for cows and horses to sleep inside? Tap the picture.$q$, $q$[{"text":"barn","is_correct":true,"tile":{"kind":"object_group","image":"barn","count":1}},{"text":"cup","is_correct":false,"tile":{"kind":"object_group","image":"cup","count":1}},{"text":"box","is_correct":false,"tile":{"kind":"object_group","image":"box","count":1}}]$q$::jsonb, $q$barn$q$, $q$A barn is gigantic. It is a big building on a farm where cows and horses can sleep. A box and a cup are small.$q$,
   'audio_picture', null::jsonb),
  ('3e90b8df-982c-5b0b-a047-5b645b156dba', (select id from public.skills where slug = 'read-gk-vocabulary'), 'hard',
   $q$Sturdy means strong and hard to break. Which one is sturdy enough for you to sit on? Tap the picture.$q$, $q$[{"text":"egg","is_correct":false,"tile":{"kind":"object_group","image":"egg","count":1}},{"text":"cupcake","is_correct":false,"tile":{"kind":"object_group","image":"cupcake","count":1}},{"text":"chair","is_correct":true,"tile":{"kind":"object_group","image":"chair","count":1}}]$q$::jsonb, $q$chair$q$, $q$A chair is sturdy. It is strong and holds you up. A cupcake would squish, and an egg would crack.$q$,
   'audio_picture', null::jsonb),
  ('0faaa1cf-2010-5fd1-bc41-0b33bf1b2787', (select id from public.skills where slug = 'read-gk-vocabulary'), 'easy',
   $q$You are making a sand castle at the beach. Which one could you use to carry water and sand? Tap the picture.$q$, $q$[{"text":"pencil","is_correct":false,"tile":{"kind":"object_group","image":"pencil","count":1}},{"text":"bucket","is_correct":true,"tile":{"kind":"object_group","image":"bucket","count":1}},{"text":"hat","is_correct":false,"tile":{"kind":"object_group","image":"hat","count":1}}]$q$::jsonb, $q$bucket$q$, $q$A bucket can carry water and sand. It has a handle so you can hold it. A pencil is for writing.$q$,
   'audio_picture', null::jsonb),
  ('e837f11c-b737-55f0-9540-e1e601597a96', (select id from public.skills where slug = 'read-gk-vocabulary'), 'easy',
   $q$Which one helps people see better? Tap the picture.$q$, $q$[{"text":"glasses","is_correct":true,"tile":{"kind":"object_group","image":"glasses","count":1}},{"text":"cookie","is_correct":false,"tile":{"kind":"object_group","image":"cookie","count":1}},{"text":"drum","is_correct":false,"tile":{"kind":"object_group","image":"drum","count":1}}]$q$::jsonb, $q$glasses$q$, $q$Glasses help people see better. You wear them on your face, in front of your eyes.$q$,
   'audio_picture', null::jsonb),
  ('377e4f69-3804-55ab-af71-0af2d76f78eb', (select id from public.skills where slug = 'read-gk-vocabulary'), 'easy',
   $q$Oops, the juice spilled all over the floor! Which one would you use to clean up the mess? Tap the picture.$q$, $q$[{"text":"mop","is_correct":true,"tile":{"kind":"object_group","image":"mop","count":1}},{"text":"cake","is_correct":false,"tile":{"kind":"object_group","image":"cake","count":1}},{"text":"kite","is_correct":false,"tile":{"kind":"object_group","image":"kite","count":1}}]$q$::jsonb, $q$mop$q$, $q$A mop cleans up a wet, messy floor. You push it back and forth to soak up the spill.$q$,
   'audio_picture', null::jsonb),
  ('5659be19-6199-504c-93f2-e16bc30d8b59', (select id from public.skills where slug = 'read-gk-vocabulary'), 'easy',
   $q$Which one could you pack in your lunch bag to eat at school? Tap the picture.$q$, $q$[{"text":"shoe","is_correct":false,"tile":{"kind":"object_group","image":"shoe","count":1}},{"text":"lamp","is_correct":false,"tile":{"kind":"object_group","image":"lamp","count":1}},{"text":"sandwich","is_correct":true,"tile":{"kind":"object_group","image":"sandwich","count":1}}]$q$::jsonb, $q$sandwich$q$, $q$A sandwich is a lunch food. You can pack it in a bag and eat it at school. A shoe and a lamp are not food.$q$,
   'audio_picture', null::jsonb),
  ('ecef739e-07df-5b32-8ad0-4208567bc81c', (select id from public.skills where slug = 'read-gk-vocabulary'), 'medium',
   $q$A vehicle is something that carries people from place to place. Which one is a vehicle that rides on tracks? Tap the picture.$q$, $q$[{"text":"chair","is_correct":false,"tile":{"kind":"object_group","image":"chair","count":1}},{"text":"train","is_correct":true,"tile":{"kind":"object_group","image":"train","count":1}},{"text":"bowl","is_correct":false,"tile":{"kind":"object_group","image":"bowl","count":1}}]$q$::jsonb, $q$train$q$, $q$A train is a vehicle. It carries people along metal tracks. A chair and a bowl cannot take you anywhere.$q$,
   'audio_picture', null::jsonb),
  ('a38b810f-e3c8-5d6f-a75f-86ccf617af8a', (select id from public.skills where slug = 'read-gk-vocabulary'), 'medium',
   $q$Your cat is stuck up in a tree. Which one could help you climb up high to reach it? Tap the picture.$q$, $q$[{"text":"ladder","is_correct":true,"tile":{"kind":"object_group","image":"ladder","count":1}},{"text":"mitten","is_correct":false,"tile":{"kind":"object_group","image":"mitten","count":1}},{"text":"sandwich","is_correct":false,"tile":{"kind":"object_group","image":"sandwich","count":1}}]$q$::jsonb, $q$ladder$q$, $q$A ladder has steps you can climb, one at a time, to reach high places like a tree branch.$q$,
   'audio_picture', null::jsonb),
  ('3107bcc2-f15a-5fd8-9942-026325f6a568', (select id from public.skills where slug = 'read-gk-vocabulary'), 'medium',
   $q$Furniture means the big things in a home that we sit on, sleep on, or put things on. Which one is furniture? Tap the picture.$q$, $q$[{"text":"table","is_correct":true,"tile":{"kind":"object_group","image":"table","count":1}},{"text":"frog","is_correct":false,"tile":{"kind":"object_group","image":"frog","count":1}},{"text":"apple","is_correct":false,"tile":{"kind":"object_group","image":"apple","count":1}}]$q$::jsonb, $q$table$q$, $q$A table is furniture. We put plates and books on a table. An apple is a food, and a frog is an animal.$q$,
   'audio_picture', null::jsonb),
  ('3b8701c1-86fc-5e6c-b39c-cebca5e2a8c6', (select id from public.skills where slug = 'read-gk-vocabulary'), 'hard',
   $q$Listen. A bird builds a nest out of sticks and grass to keep its eggs safe. Which one is a nest? Tap the picture.$q$, $q$[{"text":"flag","is_correct":false,"tile":{"kind":"object_group","image":"flag","count":1}},{"text":"nest","is_correct":true,"tile":{"kind":"object_group","image":"nest","count":1}},{"text":"comb","is_correct":false,"tile":{"kind":"object_group","image":"comb","count":1}}]$q$::jsonb, $q$nest$q$, $q$A nest is a cozy home a bird makes from sticks and grass. Baby birds hatch from eggs in the nest.$q$,
   'audio_picture', null::jsonb),
  ('bbe426cf-a58f-51da-aa6b-abfb69057c90', (select id from public.skills where slug = 'read-gk-vocabulary'), 'hard',
   $q$Listen. A harvest is when farmers pick the food that grew in their fields. In the fall, farmers harvest a tall yellow vegetable. Which one would a farmer harvest? Tap the picture.$q$, $q$[{"text":"bell","is_correct":false,"tile":{"kind":"object_group","image":"bell","count":1}},{"text":"corn","is_correct":true,"tile":{"kind":"object_group","image":"corn","count":1}},{"text":"bike","is_correct":false,"tile":{"kind":"object_group","image":"bike","count":1}}]$q$::jsonb, $q$corn$q$, $q$Farmers harvest corn from their fields. Corn grows on tall stalks. A bike and a bell do not grow.$q$,
   'audio_picture', null::jsonb)
  ) as v (id, skill_id, difficulty, stem, choices, correct_answer, solution, render_mode, prompt)
on conflict (id) do update set
  skill_id       = excluded.skill_id,
  difficulty     = excluded.difficulty,
  stem           = excluded.stem,
  choices        = excluded.choices,
  correct_answer = excluded.correct_answer,
  solution       = excluded.solution,
  render_mode    = excluded.render_mode,
  prompt         = excluded.prompt,
  status         = excluded.status;

-- ---- read-g6-vocabulary-in-context: Vocabulary in Context, grade 6 (6-8), 40 questions ----
