insert into public.skills (id, level, parent_id, subject, name, slug, grade_band, ccss_grade, ccss_grade_num, ccss_code,
                           sat_alignment, prerequisite_skills)
values ('f42241e3-b3f8-50cd-aa2c-18f1fc20a571', 'skill', '2f96d151-0a4d-5922-b8ea-ac6de3ef7406', 'reading', $q$Vocabulary in Context$q$, 'read-g6-vocabulary-in-context',
