insert into public.skill_standard_codes (skill_id, framework, code)
select s.id, t.framework, t.code
  from public.skills s
 cross join (values ('ccss', $q$L.6.4a$q$), ('ccss', $q$L.7.4a$q$), ('ccss', $q$L.8.4a$q$)) as t (framework, code)
 where s.slug = 'read-g6-vocabulary-in-context'
on conflict do nothing;

insert into public.generated_questions
  (id, skill_id, difficulty, stem, choices, correct_answer, solution, render_mode, prompt, status, template_id, sat_alignment, passage_id)
select v.id::uuid, v.skill_id, v.difficulty::public.question_difficulty, v.stem, v.choices, v.correct_answer, v.solution,
       v.render_mode, v.prompt, 'published', null, null, null
  from (values
  ('b336389d-8667-5aa6-8548-91941f74dedd', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentences. "Rosa was meticulous about her science notebook. She labeled every drawing, dated every page, and checked each measurement twice." As used in the sentences, "meticulous" most nearly means:$q$, $q$[{"text":"quick and eager to finish","is_correct":false,"misconception_token":"contradicts-text"},{"text":"very careful about details","is_correct":true},{"text":"proud of her good grades","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"talented at drawing pictures","is_correct":false,"misconception_token":"out-of-scope"}]$q$::jsonb, $q$very careful about details$q$, $q$The second sentence gives examples: labeling every drawing, dating every page, and checking twice all show close attention to detail. Being "quick and eager to finish" is the opposite, since checking everything twice takes extra time.$q$,
   'text', null::jsonb),
  ('514719f6-ddbc-5382-abc3-7f65c1f6a624', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "Marcus was reluctant to jump into the cold lake, so he stood on the dock for ten minutes while his friends splashed below." As used in the sentence, "reluctant" most nearly means:$q$, $q$[{"text":"unable to swim","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"eager and ready","is_correct":false,"misconception_token":"contradicts-text"},{"text":"angry at his friends","is_correct":false,"misconception_token":"out-of-scope"},{"text":"unwilling or hesitant","is_correct":true}]$q$::jsonb, $q$unwilling or hesitant$q$, $q$The effect clue is that he "stood on the dock for ten minutes" instead of jumping, which shows he did not want to go in. Nothing says he was "unable to swim"; he simply held back because the water was cold.$q$,
   'text', null::jsonb),
  ('8823a6e7-daca-5e0b-836c-6dc23eeab9af', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentences. "The team packed ample water for the long hike. There was enough for everyone to drink, with several bottles left over at the end." As used in the sentences, "ample" most nearly means:$q$, $q$[{"text":"barely enough","is_correct":false,"misconception_token":"contradicts-text"},{"text":"too heavy to carry","is_correct":false,"misconception_token":"out-of-scope"},{"text":"more than enough","is_correct":true},{"text":"cold and refreshing","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$more than enough$q$, $q$The second sentence restates the meaning: there was enough for everyone, "with several bottles left over." That leftover water rules out "barely enough," which would mean nothing was left.$q$,
   'text', null::jsonb),
  ('497a554e-09a7-5409-8288-e181e1e3934d', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentences. "Coach Lee gave a candid answer when a reporter asked about the loss. She said plainly that the team had not practiced hard enough." As used in the sentences, "candid" most nearly means:$q$, $q$[{"text":"polite but vague","is_correct":false,"misconception_token":"contradicts-text"},{"text":"angry and loud","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"unposed, like a snapshot","is_correct":false,"misconception_token":"wrong-word-meaning"},{"text":"honest and direct","is_correct":true}]$q$::jsonb, $q$honest and direct$q$, $q$The clue "said plainly" restates candid as honest and straightforward. A "candid" photo is unposed, but that meaning fits pictures, not an answer to a reporter's question.$q$,
   'text', null::jsonb),
  ('c932154e-5b27-5863-b027-a342638f9102', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "The ancient vase was so fragile that the museum kept it behind glass, and workers wore soft gloves to move it." As used in the sentence, "fragile" most nearly means:$q$, $q$[{"text":"worth a lot of money","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"brightly painted","is_correct":false,"misconception_token":"out-of-scope"},{"text":"easily broken","is_correct":true},{"text":"strong and sturdy","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$easily broken$q$, $q$The cause and effect clue is that the vase was so fragile that it needed glass and soft gloves, which protect something that could break. It may be valuable, but "worth a lot of money" does not explain why workers had to handle it so gently.$q$,
   'text', null::jsonb),
  ('28b4ff69-2eff-57a8-9938-80208a2d7d86', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentences. "The hiker was cautious on the icy trail. She tested each step with her pole before putting her weight down." What does "cautious" mean as it is used here?$q$, $q$[{"text":"proud of her strength","is_correct":false,"misconception_token":"out-of-scope"},{"text":"lost and confused","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"careless and hurried","is_correct":false,"misconception_token":"contradicts-text"},{"text":"careful to avoid danger","is_correct":true}]$q$::jsonb, $q$careful to avoid danger$q$, $q$The example in the second sentence, testing each step before trusting it, shows she was being careful to stay safe. "Careless and hurried" is the opposite of slowly testing every step.$q$,
   'text', null::jsonb),
  ('72f1c75d-1454-5ceb-ab01-ba0311f7f8b1', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "When Priya read her name on the list of contest winners, she was so elated that she jumped up and hugged her sister." As used in the sentence, "elated" most nearly means:$q$, $q$[{"text":"worried about the prize","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"deeply disappointed","is_correct":false,"misconception_token":"contradicts-text"},{"text":"extremely happy","is_correct":true},{"text":"hungry for a snack","is_correct":false,"misconception_token":"out-of-scope"}]$q$::jsonb, $q$extremely happy$q$, $q$The general sense of the sentence gives the meaning: she won, then jumped up and hugged her sister, which are signs of great joy. "Deeply disappointed" does not fit someone who just learned she was a winner.$q$,
   'text', null::jsonb),
  ('2fdbb327-065b-5890-a528-8266dfa45b2b', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "Diligent students in the robotics club stayed after school every day, fixing code and testing their robot until it worked." As used in the sentence, "diligent" most nearly means:$q$, $q$[{"text":"popular with classmates","is_correct":false,"misconception_token":"out-of-scope"},{"text":"hardworking and steady","is_correct":true},{"text":"lazy and careless","is_correct":false,"misconception_token":"contradicts-text"},{"text":"gifted with computers","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$hardworking and steady$q$, $q$The examples show the meaning: staying every day and testing "until it worked" describes steady, hard effort. Being "gifted with computers" is tempting because of the robot, but the sentence praises their effort, not a natural talent.$q$,
   'text', null::jsonb),
  ('17d91344-465c-5481-9ce2-5bfaa930b51c', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "The author's vivid description of the market let readers almost smell the spices and hear the shouting sellers." As used in the sentence, "vivid" most nearly means:$q$, $q$[{"text":"clear and full of life","is_correct":true},{"text":"bright in color only","is_correct":false,"misconception_token":"too-narrow"},{"text":"very long and detailed","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"dull and hard to picture","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$clear and full of life$q$, $q$The effect clue is that readers could "almost smell" and "hear" the market, so the writing brings the scene to life for every sense. "Bright in color only" is too narrow, because the description reaches smell and sound, not just sight.$q$,
   'text', null::jsonb),
  ('8831979b-3829-572b-b15f-3cd712cb230b', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "Unlike the friendly dogs at the park, the stray was hostile, growling and baring its teeth at anyone who came near." As used in the sentence, "hostile" most nearly means:$q$, $q$[{"text":"hungry and thin","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"playful and gentle","is_correct":false,"misconception_token":"contradicts-text"},{"text":"unfriendly and threatening","is_correct":true},{"text":"small and quiet","is_correct":false,"misconception_token":"out-of-scope"}]$q$::jsonb, $q$unfriendly and threatening$q$, $q$The contrast word "Unlike" sets the stray against "friendly" dogs, and growling and baring teeth are signs of a threat. "Playful and gentle" describes the friendly dogs, which is the opposite of the stray.$q$,
   'text', null::jsonb),
  ('14f11540-5684-578b-84a5-1a49d53759ac', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "Fresh water was scarce on the island, so the sailors collected rain in barrels and drank only small sips each day." As used in the sentence, "scarce" most nearly means:$q$, $q$[{"text":"unsafe to drink","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"easy to find everywhere","is_correct":false,"misconception_token":"contradicts-text"},{"text":"in short supply","is_correct":true},{"text":"heavy to lift","is_correct":false,"misconception_token":"out-of-scope"}]$q$::jsonb, $q$in short supply$q$, $q$The effects explain the word: the sailors saved rain and drank "only small sips," which people do when there is not much. "Unsafe to drink" is not supported, because they were saving the water to drink it.$q$,
   'text', null::jsonb),
  ('75c0ebe3-3f59-5f1a-8ab4-ab61d71f78a9', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "The desert was so vast that the travelers drove for two full days without reaching the other side." As used in the sentence, "vast" most nearly means:$q$, $q$[{"text":"extremely large","is_correct":true},{"text":"small and close","is_correct":false,"misconception_token":"contradicts-text"},{"text":"noisy and crowded","is_correct":false,"misconception_token":"out-of-scope"},{"text":"hot and dry","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$extremely large$q$, $q$The cause and effect clue, driving "two full days" without crossing it, shows the desert was huge. Deserts are often "hot and dry," but the sentence describes its size, not its weather.$q$,
   'text', null::jsonb),
  ('b2f1f26d-4011-5625-a54d-b15ac9c6a660', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "Copying three hundred addresses by hand was tedious work, and by the end Jamal could barely keep his eyes open." As used in the sentence, "tedious" most nearly means:$q$, $q$[{"text":"done in a hurry","is_correct":false,"misconception_token":"out-of-scope"},{"text":"long and boring","is_correct":true},{"text":"exciting and fun","is_correct":false,"misconception_token":"contradicts-text"},{"text":"hard to understand","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$long and boring$q$, $q$Three hundred addresses is a long job, and Jamal "could barely keep his eyes open," which shows it was dull and tiring. Copying addresses is simple, so "hard to understand" does not fit.$q$,
   'text', null::jsonb),
  ('5c89f928-110b-5a26-a180-ff47321238ec', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentences. "The timid kitten hid under the bed for hours. It was shy and would come out only when the room was completely quiet." As used in the sentences, "timid" most nearly means:$q$, $q$[{"text":"bold and curious","is_correct":false,"misconception_token":"contradicts-text"},{"text":"hungry for food","is_correct":false,"misconception_token":"out-of-scope"},{"text":"shy and easily scared","is_correct":true},{"text":"sick and weak","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$shy and easily scared$q$, $q$The synonym "shy" in the second sentence, plus hiding until the room was quiet, shows the kitten was fearful. "Bold and curious" would describe a kitten that came out to explore, the opposite of hiding.$q$,
   'text', null::jsonb),
  ('f2f076f4-d7ed-5912-beb6-37c1c0d80d87', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "Unlike her old sneakers, which fell apart in a month, Ana's new hiking boots were durable enough to last for years." As used in the sentence, "durable" most nearly means:$q$, $q$[{"text":"brightly colored","is_correct":false,"misconception_token":"out-of-scope"},{"text":"weak and easy to tear","is_correct":false,"misconception_token":"contradicts-text"},{"text":"soft and comfortable","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"strong and long lasting","is_correct":true}]$q$::jsonb, $q$strong and long lasting$q$, $q$The contrast clue "Unlike" sets the boots against sneakers that "fell apart in a month," and the boots will "last for years." Good boots may be "soft and comfortable," but the sentence only talks about how long they last.$q$,
   'text', null::jsonb),
  ('343c128f-56ee-5296-b1e8-aade8c5f8daf', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'easy',
   $q$Read the sentence. "The club came up with a novel way to raise money: a dog walking service that no other group at school had ever tried." As used in the sentence, "novel" most nearly means:$q$, $q$[{"text":"old and familiar","is_correct":false,"misconception_token":"contradicts-text"},{"text":"risky and unsafe","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"a long story in a book","is_correct":false,"misconception_token":"wrong-word-meaning"},{"text":"new and unusual","is_correct":true}]$q$::jsonb, $q$new and unusual$q$, $q$The clue is that "no other group at school had ever tried" the idea, so it was new. A "novel" can be a long book, but here the word describes a way to raise money, not something you read.$q$,
   'text', null::jsonb),
  ('6ab1733d-93fa-55e4-9e69-1a28ed37928c', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentences. "The coral reef proved resilient. After a strong storm broke many of its branches, new growth covered the damage within a few years." As used in the sentences, "resilient" most nearly means:$q$, $q$[{"text":"able to recover after harm","is_correct":true},{"text":"easily destroyed for good","is_correct":false,"misconception_token":"contradicts-text"},{"text":"quick to grow taller","is_correct":false,"misconception_token":"too-narrow"},{"text":"safe from every storm","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$able to recover after harm$q$, $q$The cause and effect clue shows the reef was damaged and then grew back, which is bouncing back from harm. "Safe from every storm" is wrong because the storm did break its branches; the reef recovered rather than avoided damage.$q$,
   'text', null::jsonb),
  ('536d3a9e-f090-5816-be69-1b1a3423352f', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentences. "Without regular painting, the wooden fence began to deteriorate. Boards cracked, nails rusted, and one section finally collapsed." As used in the sentences, "deteriorate" most nearly means:$q$, $q$[{"text":"grow stronger with age","is_correct":false,"misconception_token":"contradicts-text"},{"text":"get replaced by a wall","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"slowly change color","is_correct":false,"misconception_token":"too-narrow"},{"text":"become worse over time","is_correct":true}]$q$::jsonb, $q$become worse over time$q$, $q$The examples, cracked boards, rusted nails, and a collapsed section, show the fence falling apart little by little. Fading paint would be one small sign, so "slowly change color" is too narrow for all that damage.$q$,
   'text', null::jsonb),
  ('9ec23023-9019-55f5-baf2-9f8625d66473', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentences. "My grandfather is frugal. He repairs his own shoes, buys used books, and saves every spare coin in a jar." As used in the sentences, "frugal" most nearly means:$q$, $q$[{"text":"skilled at fixing things","is_correct":false,"misconception_token":"too-narrow"},{"text":"careful about spending money","is_correct":true},{"text":"generous with his money","is_correct":false,"misconception_token":"contradicts-text"},{"text":"poor and struggling to pay","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$careful about spending money$q$, $q$The examples all show someone avoiding needless spending: repairing instead of buying, buying used, and saving coins. "Poor and struggling to pay" is tempting, but the sentences show a habit of saving, not a lack of money.$q$,
   'text', null::jsonb),
  ('17063f1d-ee9f-5e79-bd4e-ba0e05c88a22', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "Dark clouds gathered over the stadium, and an ominous rumble of thunder made the fans glance nervously at the sky." As used in the sentence, "ominous" most nearly means:$q$, $q$[{"text":"louder than anything else","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"cheerful and comforting","is_correct":false,"misconception_token":"contradicts-text"},{"text":"musical and rhythmic","is_correct":false,"misconception_token":"out-of-scope"},{"text":"warning that trouble is coming","is_correct":true}]$q$::jsonb, $q$warning that trouble is coming$q$, $q$The clues "Dark clouds" and fans glancing "nervously" show the thunder signals a coming storm. Thunder is loud, but "louder than anything else" misses why the fans felt nervous.$q$,
   'text', null::jsonb),
  ('aa91d935-6bd7-5bef-84cd-b293d9a0453a', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "In a room full of people dressed in black, Ella's bright yellow raincoat made her conspicuous." As used in the sentence, "conspicuous" most nearly means:$q$, $q$[{"text":"very fashionable","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"hard to spot","is_correct":false,"misconception_token":"contradicts-text"},{"text":"warm and dry","is_correct":false,"misconception_token":"out-of-scope"},{"text":"easy to notice","is_correct":true}]$q$::jsonb, $q$easy to notice$q$, $q$The contrast between bright yellow and a room "full of people dressed in black" shows Ella stood out. Nothing says her coat was "very fashionable"; it only made her stand out.$q$,
   'text', null::jsonb),
  ('6ed744f3-c7c9-5bf4-848f-a49a3c5c384c', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "Dr. Park was skeptical of the claim that the bean plant grew a foot overnight, so she asked to see the student's measurements." As used in the sentence, "skeptical" most nearly means:$q$, $q$[{"text":"doubtful and needing proof","is_correct":true},{"text":"insulted and angry","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"impressed and excited","is_correct":false,"misconception_token":"contradicts-text"},{"text":"busy and distracted","is_correct":false,"misconception_token":"out-of-scope"}]$q$::jsonb, $q$doubtful and needing proof$q$, $q$The effect clue is that she "asked to see the measurements," which is what someone does when they want proof before believing. "Impressed and excited" would mean she accepted the claim without checking.$q$,
   'text', null::jsonb),
  ('e71a4ced-322b-5fec-9641-421e5c8a3170', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "Sweeping the sidewalk during the windstorm was futile, because the leaves blew right back as soon as they were swept away." As used in the sentence, "futile" most nearly means:$q$, $q$[{"text":"noisy and disturbing","is_correct":false,"misconception_token":"out-of-scope"},{"text":"helpful and worth doing","is_correct":false,"misconception_token":"contradicts-text"},{"text":"having no useful result","is_correct":true},{"text":"dangerous to attempt","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$having no useful result$q$, $q$The cause clue "because the leaves blew right back" shows the sweeping accomplished nothing. A windstorm might seem "dangerous," but the sentence explains that the work was pointless, not risky.$q$,
   'text', null::jsonb),
  ('80d8613d-74e6-5ee9-9eba-c50476f03b6e', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentences. "Ms. Ortiz was lenient about the late project. Instead of taking off points, she gave Leo two extra days to finish." As used in the sentences, "lenient" most nearly means:$q$, $q$[{"text":"worried and upset","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"busy and rushed","is_correct":false,"misconception_token":"out-of-scope"},{"text":"forgiving and not strict","is_correct":true},{"text":"strict and demanding","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$forgiving and not strict$q$, $q$The contrast "Instead of taking off points" shows she chose not to punish Leo and gave him more time. "Strict and demanding" describes a teacher who would take off points, the opposite of what she did.$q$,
   'text', null::jsonb),
  ('2fa42592-9f00-58c3-943c-678bc9312bfa', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "The editor asked Nia to make her report more concise, so she cut it from four pages to one without losing any key facts." As used in the sentence, "concise" most nearly means:$q$, $q$[{"text":"longer and more detailed","is_correct":false,"misconception_token":"contradicts-text"},{"text":"brief but still complete","is_correct":true},{"text":"shorter, whatever is lost","is_correct":false,"misconception_token":"too-narrow"},{"text":"more exciting to read","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$brief but still complete$q$, $q$The restatement shows two parts: the report got shorter, and it kept "any key facts." "Shorter, whatever is lost" captures only the first part and ignores that nothing important was cut.$q$,
   'text', null::jsonb),
  ('1cf12c63-05f6-543e-bba8-3dd82aa61e8d', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "The volcano had been dormant for two hundred years, but scientists warned that it could erupt again at any time." As used in the sentence, "dormant" most nearly means:$q$, $q$[{"text":"very dangerous","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"gone for good","is_correct":false,"misconception_token":"contradicts-text"},{"text":"hidden from view","is_correct":false,"misconception_token":"out-of-scope"},{"text":"inactive for now","is_correct":true}]$q$::jsonb, $q$inactive for now$q$, $q$The contrast word "but" shows the volcano has been quiet yet "could erupt again," so it is resting, not finished. That warning rules out "gone for good," which would mean it could never erupt.$q$,
   'text', null::jsonb),
  ('82b7e8db-5293-54db-8960-639649d47bcb', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "The student council tabled the proposal for a new mascot, agreeing to set it aside until the spring meeting." As used in the sentence, "tabled" most nearly means:$q$, $q$[{"text":"rejected forever","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"approved right away","is_correct":false,"misconception_token":"contradicts-text"},{"text":"put off until later","is_correct":true},{"text":"set on a piece of furniture","is_correct":false,"misconception_token":"wrong-word-meaning"}]$q$::jsonb, $q$put off until later$q$, $q$The restatement "set it aside until the spring meeting" shows the council delayed the decision. A table is furniture, but here "tabled" describes what a group does with an idea, not where they put an object.$q$,
   'text', null::jsonb),
  ('836f5d4b-c7de-5ca5-bd70-822bdddbeae4', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "Thanks to a warm, rainy spring, the orchard should yield nearly twice as many apples as it did last year." As used in the sentence, "yield" most nearly means:$q$, $q$[{"text":"lose or waste","is_correct":false,"misconception_token":"contradicts-text"},{"text":"produce","is_correct":true},{"text":"sell at a market","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"give way to traffic","is_correct":false,"misconception_token":"wrong-word-meaning"}]$q$::jsonb, $q$produce$q$, $q$The general sense is that good weather helps the orchard grow "twice as many apples," so yield means produce. Drivers yield by giving way to traffic, but an orchard does not drive, so that meaning does not fit.$q$,
   'text', null::jsonb),
  ('cf0145a9-6fe6-5773-bcee-6a9d518fff0a', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "The judges called Kara's experiment plan sound, since every step was based on careful research." As used in the sentence, "sound" most nearly means:$q$, $q$[{"text":"weak and full of errors","is_correct":false,"misconception_token":"contradicts-text"},{"text":"noisy and easy to hear","is_correct":false,"misconception_token":"wrong-word-meaning"},{"text":"unusual and original","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"reliable and well reasoned","is_correct":true}]$q$::jsonb, $q$reliable and well reasoned$q$, $q$The cause clue "since every step was based on careful research" shows the plan was solid and trustworthy. "Sound" often names something you hear, but a written plan does not make noise.$q$,
   'text', null::jsonb),
  ('45cc4a91-1a5c-508c-b165-8e304efa6191', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "Even after the two friends made up, Theo continued to harbor a grudge, quietly holding on to his anger for weeks." As used in the sentence, "harbor" most nearly means:$q$, $q$[{"text":"let go of completely","is_correct":false,"misconception_token":"contradicts-text"},{"text":"keep inside one's mind","is_correct":true},{"text":"shelter ships near shore","is_correct":false,"misconception_token":"wrong-word-meaning"},{"text":"shout out loudly","is_correct":false,"misconception_token":"out-of-scope"}]$q$::jsonb, $q$keep inside one's mind$q$, $q$The restatement "quietly holding on to his anger" explains that he kept the grudge inside. A harbor is a place where ships stay safe, but Theo is holding a feeling, not ships.$q$,
   'text', null::jsonb),
  ('52fde97f-2b00-51d1-8c68-73effaf520ea', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "When the starting gun fired, the runner bolted from the line and took the lead within seconds." As used in the sentence, "bolted" most nearly means:$q$, $q$[{"text":"tripped and fell","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"ran off suddenly","is_correct":true},{"text":"walked off slowly","is_correct":false,"misconception_token":"contradicts-text"},{"text":"locked with a metal bar","is_correct":false,"misconception_token":"wrong-word-meaning"}]$q$::jsonb, $q$ran off suddenly$q$, $q$The clues "starting gun" and "took the lead within seconds" show a sudden, fast start. A door can be bolted, meaning locked, but a runner leaving a starting line is not being locked.$q$,
   'text', null::jsonb),
  ('15c13a6e-6cc3-57b6-a29c-e8533ca52a2f', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'medium',
   $q$Read the sentence. "Once phones could take sharp pictures, many families found their old film cameras obsolete and packed them away in the attic." As used in the sentence, "obsolete" most nearly means:$q$, $q$[{"text":"small and easy to carry","is_correct":false,"misconception_token":"out-of-scope"},{"text":"out of date and no longer used","is_correct":true},{"text":"broken and needing repair","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"brand new and in demand","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$out of date and no longer used$q$, $q$The cause clue is that phones replaced what the cameras did, so families stopped using them. Nothing says the cameras were "broken and needing repair"; they still worked but had been replaced by something newer.$q$,
   'text', null::jsonb),
  ('8353ec2c-1138-5d76-8635-0c5b9dc8e684', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'hard',
   $q$Read the sentence. "The captain's face was grave as he told the crew that the storm had damaged the engine and they were still far from shore." As used in the sentence, "grave" most nearly means:$q$, $q$[{"text":"tired and sleepy","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"serious and worried","is_correct":true},{"text":"a place of burial","is_correct":false,"misconception_token":"wrong-word-meaning"},{"text":"calm and cheerful","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$serious and worried$q$, $q$The general sense of the bad news, a damaged engine far from shore, tells how the captain looked: serious. A grave is also a burial place, but here the word describes a face, so it must be an adjective about mood.$q$,
   'text', null::jsonb),
  ('1b61f04f-e7cf-54e7-91a6-37eba47ecda9', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'hard',
   $q$Read the sentence. "For twenty years the scientist championed protecting the wetlands, writing letters to leaders and speaking at town meetings." As used in the sentence, "championed" most nearly means:$q$, $q$[{"text":"argued against and opposed","is_correct":false,"misconception_token":"contradicts-text"},{"text":"spoke up for and supported","is_correct":true},{"text":"studied closely in a lab","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"won first place in a contest","is_correct":false,"misconception_token":"wrong-word-meaning"}]$q$::jsonb, $q$spoke up for and supported$q$, $q$The examples, writing letters and speaking at meetings, show someone fighting for a cause. A champion can be a contest winner, but no contest is mentioned; here the verb means supporting an idea in public.$q$,
   'text', null::jsonb),
  ('f048d442-a1af-5e20-9495-7091aa842838', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'hard',
   $q$Read the sentences. "Lena felt ambivalent about moving to a new city. She was excited to have her own room, but she dreaded leaving her best friend behind." As used in the sentences, "ambivalent" most nearly means:$q$, $q$[{"text":"angry at her parents","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"thrilled and excited","is_correct":false,"misconception_token":"too-narrow"},{"text":"calm and certain","is_correct":false,"misconception_token":"contradicts-text"},{"text":"having mixed feelings","is_correct":true}]$q$::jsonb, $q$having mixed feelings$q$, $q$The contrast word "but" joins two opposite feelings, excitement and dread, so Lena feels both at once. "Thrilled and excited" is too narrow because it keeps only the happy half and drops the dread.$q$,
   'text', null::jsonb),
  ('cc07ef25-0bfb-5aeb-8255-bfd97845e258', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'hard',
   $q$Read the sentence. "Rather than design a costly new playground, the pragmatic committee fixed the old swings and added benches, a plan that fit the budget and could be finished by summer." As used in the sentence, "pragmatic" most nearly means:$q$, $q$[{"text":"full of big, imaginative dreams","is_correct":false,"misconception_token":"contradicts-text"},{"text":"unwilling to do any real work","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"concerned only with saving money","is_correct":false,"misconception_token":"too-narrow"},{"text":"focused on what will actually work","is_correct":true}]$q$::jsonb, $q$focused on what will actually work$q$, $q$The clues show the committee chose a plan that "fit the budget and could be finished by summer," which is a practical choice. "Concerned only with saving money" is too narrow, because the plan also had to be doable on time and still improve the playground.$q$,
   'text', null::jsonb),
  ('d05af32a-d988-59d0-9050-22709d67c5a0', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'hard',
   $q$Read the sentence. "Before signing the contract, the band's manager scrutinized every line, searching for hidden fees and confusing terms." As used in the sentence, "scrutinized" most nearly means:$q$, $q$[{"text":"examined very closely","is_correct":true},{"text":"skimmed very quickly","is_correct":false,"misconception_token":"contradicts-text"},{"text":"praised in public","is_correct":false,"misconception_token":"out-of-scope"},{"text":"rewrote in new words","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$examined very closely$q$, $q$The clue "searching for hidden fees and confusing terms" in "every line" shows careful, detailed reading. "Skimmed very quickly" is the opposite, since skimming would miss hidden details.$q$,
   'text', null::jsonb),
  ('82c1d8cb-4891-5c69-be25-dafa90a71fed', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'hard',
   $q$Read the sentence. "The benevolent shop owner quietly paid for school supplies for every student whose family could not afford them." As used in the sentence, "benevolent" most nearly means:$q$, $q$[{"text":"selfish and greedy","is_correct":false,"misconception_token":"contradicts-text"},{"text":"kind and generous","is_correct":true},{"text":"quiet and private","is_correct":false,"misconception_token":"too-narrow"},{"text":"wealthy and successful","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$kind and generous$q$, $q$The example of paying for other students' supplies shows kindness and giving. "Wealthy and successful" is tempting, but the sentence shows what the owner chose to do, not how much money the owner has.$q$,
   'text', null::jsonb),
  ('f1d01d60-b14d-5775-bbf9-a8647c84c085', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'hard',
   $q$Read the sentence. "The sand sculptures on the beach were ephemeral; by the next morning, the tide had washed every one of them away." As used in the sentence, "ephemeral" most nearly means:$q$, $q$[{"text":"lasting a very short time","is_correct":true},{"text":"lasting for many years","is_correct":false,"misconception_token":"contradicts-text"},{"text":"beautiful and detailed","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"heavy and hard to move","is_correct":false,"misconception_token":"out-of-scope"}]$q$::jsonb, $q$lasting a very short time$q$, $q$The clause after the semicolon explains the word: by the next morning the sculptures were gone, so they did not last. They may have been "beautiful and detailed," but the sentence is about how long they lasted, not how they looked.$q$,
   'text', null::jsonb),
  ('5c3bccb5-4e0d-5b77-b201-186d22601bc5', (select id from public.skills where slug = 'read-g6-vocabulary-in-context'), 'hard',
   $q$Read the sentence. "Scratching a mosquito bite only exacerbates the itch, making the skin redder and more irritated than before." As used in the sentence, "exacerbates" most nearly means:$q$, $q$[{"text":"soothes and calms","is_correct":false,"misconception_token":"contradicts-text"},{"text":"makes worse","is_correct":true},{"text":"spreads to others","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"turns redder","is_correct":false,"misconception_token":"too-narrow"}]$q$::jsonb, $q$makes worse$q$, $q$The restatement "more irritated than before" shows that scratching makes the problem worse overall. "Turns redder" is too narrow, since redness is only one sign and the itch and irritation grow too.$q$,
   'text', null::jsonb)
  ) as v (id, skill_id, difficulty, stem, choices, correct_answer, solution, render_mode, prompt)
on conflict (id) do update set
  skill_id       = excluded.skill_id,
  difficulty     = excluded.difficulty,
  stem           = excluded.stem,
  choices        = excluded.choices,
  correct_answer = excluded.correct_answer,
  solution       = excluded.solution,
  render_mode    = excluded.render_mode,
  prompt         = excluded.prompt,
  status         = excluded.status;

